import re
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.admin.admin_factory import AdminBaseClass
from taf.ul.trs_e2e_fw.lib.oam.exceptions import ParameterMappingSearchException, OperatorUnsupportedException
from taf.ul.trs_e2e_fw.lib.utils.string_format import decode_str

logger = BackgroundLogger.Instance()


class ParameterMapper(AdminBaseClass):
    """
    ParameterMapper
    """
    def __init__(self):
        super(ParameterMapper, self).__init__()

    def get_moc_name_and_param_value_dict_for_input_mapping(self, query):
        try:
            result_dict = {}
            infomodel_query_temp = query
            infomodel_query_temp = infomodel_query_temp.replace("get object", "").strip().split(' is ')
            moc_name = infomodel_query_temp[0].split('/')[-1]
            moc_name = moc_name.split("-")[0]
            query_param=infomodel_query_temp[1].split(",")
            param_value_dict = {}
            seperator = ['>=', '<=', '!=','=', '>', '<']
            for param in query_param:
                param = str(param).strip()
                for sep in seperator:
                    if sep in param:
                        param = param.split(sep)
                        result_dict[param[0].strip('[').strip()] = {'operator' : sep, 'value' : param[1].strip(']').strip()}
                        break
            for key, value in result_dict.items():
                if value['operator'] == '=': 
                    param_value_dict[key] = value['value']
                else:
                    continue

            logger.debug("param value dict is :{}".format(param_value_dict))
            return moc_name, param_value_dict
        except Exception as e:
            raise e

    def search_value_in_dataframe(self, moc_name, parameter, value, flag):
        try:
            if flag == 'input_map':
                return AdminBaseClass.PARAM_VALUE_MAPPING_DATA.loc[(AdminBaseClass.PARAM_VALUE_MAPPING_DATA['MOC Name'] == moc_name) & (AdminBaseClass.PARAM_VALUE_MAPPING_DATA['Parameter Name'] == parameter) & (AdminBaseClass.PARAM_VALUE_MAPPING_DATA['Old Value'] == value), ["New Value"]].values
            if flag == 'output_map':
                return AdminBaseClass.PARAM_VALUE_MAPPING_DATA.loc[(AdminBaseClass.PARAM_VALUE_MAPPING_DATA['MOC Name'] == moc_name) & (AdminBaseClass.PARAM_VALUE_MAPPING_DATA['Parameter Name'] == parameter) & (AdminBaseClass.PARAM_VALUE_MAPPING_DATA['New Value'] == value), ["Old Value"]].values
        except Exception as e:
            raise ParameterMappingSearchException(
                            "Search failed in excel mapping for parameters due to : {}".format(e))


    def input_infomodel_query_map(self, query):
        try:
            moc_name, param_value_dict = self.get_moc_name_and_param_value_dict_for_input_mapping(query)
            logger.debug(moc_name, param_value_dict)
            if param_value_dict:
                for param, value in param_value_dict.items():
                    flag = 'input_map'
                    logger.debug("parameter : {}, value : {}".format(param, value))
                    param_search_output = self.search_value_in_dataframe(moc_name, param, value, flag)

                    if param_search_output.any():
                        param_output = re.findall('({}\s*=\s*{})'.format(param, value), query)
                        for item in param_output:
                            query = query.replace(item, item.replace(value, param_search_output[0][0]))
                logger.debug("mapped query is :{}".format(query))
            return query
        except Exception as e:
            raise e

    def output_query_infomodel_dict_map(self, output_infomodel_dict):
        try:
            moc_name = output_infomodel_dict[b'dist_name']
            moc_name = moc_name.split('/')[-1]
            moc_name = moc_name.split("-")[0]

            for param, value in output_infomodel_dict.items():
                flag = 'output_map'
                if isinstance(value, dict):
                    for parameter, param_value in value.items():
                        if isinstance(parameter, bytes):
                            param_decoded = decode_str(parameter)
                            param_search_output = ParameterMapper().search_value_in_dataframe(moc_name, '{}.{}'.format(param,param_decoded), param_value, flag)
                        else:
                            param_search_output = ParameterMapper().search_value_in_dataframe(moc_name, '{}.{}'.format(param,parameter), param_value, flag)
                        if param_search_output.any():
                            output_infomodel_dict[param][parameter] = param_search_output[0][0]        
                else:
                    if isinstance(param, bytes):
                        param_decoded = decode_str(param)
                        param_search_output = ParameterMapper().search_value_in_dataframe(moc_name, param_decoded, value, flag)
                    else:
                        param_search_output = ParameterMapper().search_value_in_dataframe(moc_name, param, value, flag)

                    if param_search_output.any():
                        output_infomodel_dict[param] = param_search_output[0][0]

            logger.debug("output mapped dict :{}".format(output_infomodel_dict))
            return output_infomodel_dict

        except Exception as e:
            raise e

    def output_query_infomodel_dict_map_get_param(self, output_infomodel_dict):
        try:
            for parameter, value in output_infomodel_dict.items():
                flag = 'output_map'
                moc_name = parameter.split('/')[-1]
                moc_name = moc_name.split("-")[0]
                for param, param_value in value.items():
                    logger.debug("param value in loop :{} type {}".format(param_value, type(param_value)))
                    if isinstance(param_value, dict):
                        for key, val in param_value.items():
                            if isinstance(param, bytes):
                                key_decoded = decode_str(key)
                                param_search_output = ParameterMapper().search_value_in_dataframe(moc_name, '{}.{}'.format(param,key_decoded), val, flag)
                            else:
                                param_search_output = ParameterMapper().search_value_in_dataframe(moc_name, '{}.{}'.format(param,key), val, flag)
                            if param_search_output.any():
                                output_infomodel_dict[parameter][param][key] = param_search_output[0][0]    
                    else:
                        if isinstance(param, bytes):
                            param_decoded = decode_str(param)
                            param_search_output = ParameterMapper().search_value_in_dataframe(moc_name, param_decoded, param_value, flag)
                        else:
                            param_search_output = ParameterMapper().search_value_in_dataframe(moc_name, param, param_value, flag)
                        if param_search_output.any():
                            output_infomodel_dict[parameter][param] = param_search_output[0][0]

            logger.debug("output mapped dict :{}".format(output_infomodel_dict))
            return output_infomodel_dict

        except Exception as e:
            raise e
